import{b as e,O as t,g as l,j as c}from"./chunks/framework.DcaUmd3X.js";const d=JSON.parse('{"title":"简单的逻辑学（湛庐经典）","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/simple-logic/index.md","filePath":"读书感悟/电子书架/8.简单的逻辑学.md","lastUpdated":1781614933000}'),p={name:"reading/digital/simple-logic/index.md"};function u(b,o,q,a,k,r){return t(),l("div",null,[...o[0]||(o[0]=[c('<h1 id="简单的逻辑学-湛庐经典" tabindex="-1">简单的逻辑学（湛庐经典） <a class="header-anchor" href="#简单的逻辑学-湛庐经典" aria-label="Permalink to &quot;简单的逻辑学（湛庐经典）&quot;">​</a></h1><p><code>D.Q.麦克伦尼</code> <code>逻辑学</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 注意力要求我们对所处的每个环境以及组成环境的每个要素都作出敏捷主动的反应。全神贯注与被动接受是不兼容的。不要对周边的事务漠然处之，要用心去看，用心去听。学会关注细节，不因事小而疏忽。古语有云：不积跬步，无以至千里。</p></blockquote><blockquote><p>📌 在逻辑学中，陈述有其特定的含义，它是语言上的特定表达方式，只针对可以作出真假判断的命题。 词语被称为语言的基石，而逻辑的基石是命题。因为只有在命题的层面上才涉及真假问题，而逻辑本身就是发现真相并将其从谬误中分离出来的学问。在命题易于理解的时候，我们可以轻易分辨出真假。但是，如果命题本身表达得含混晦涩，我们就会面临双重问题。因为我们必须先找出命题本身的含义，然后才能作出真假判断。</p></blockquote><blockquote><p>📌 在任何特定的情况下，对真相的确认都要去检查别人所认定或推测所得的真相在现实中是否存在依据。确认真相就是要达到主观与客观的统一。但是这里我们所要关注的焦点是事物的客观情况。如果我不能确认一个命题的真假，比如说“狗在车库里”，那么仅仅在大脑中反思狗啊、车库啊或者其他相关概念是无助于我解决这个问题的，我得亲自到车库去看看。从这一点也可以清楚地看出，为什么我们说本体真相更为基础。决定命题真假的依据是现实情况，而逻辑真相是建立在本体真相的基础之上的。</p></blockquote><blockquote><p>📌 逻辑定义的独特价值在于它揭示了所定义事物的本质。然而，当我们对一个事物没有足够深入的了解，不能抓住其本质时，这样的定义我们往往难以给出。在这种情况下，我们只能通过描述来宽泛地说明事物。好的描述是将一个事物可以观察到的现象尽可能完整详细地描述出来，其作用在于它可能会揭示出一些关于事物本质的线索。</p></blockquote><blockquote><p>📌 前提是一个支持性命题，它是一个论证的起点，包含着推理的出发点所依靠的基础事实。结论是被证明的命题，它在前提的基础上得出，并为大家所接受。复杂论证通常包含大量的前提，而且各前提之间往往相互作用，具有一定的关系。你可以有一整套相互关联的前提，其中一个可能建立在另一个前提之上，所以要摆正它们之间的关系，以便得出正确的结论。 失了一颗铁钉，丢了一只马蹄铁；丢了一只马蹄铁，折了一匹战马；折了一匹战马，损了一位将军；损了一位将军，输了一场战争；输了一场战争，亡了一个帝国。</p></blockquote><blockquote><p>📌 04 断言 一个命题，是某种可真可假的论断的语言表达。从语法上看，每个命题都包括一个主项和一个谓项。主项，是我们所要言说的对象，而谓项，则是我们对此对象所说的一切。断言是将谓项附着于主项的观念联结过程。“莱瑞尔是经理助理”，在这个命题中，经理助理是莱瑞尔的谓项。 如果说断言是将观念聚合并配对的过程，那么测试断言的正确性就在于聚合在一起的观念是否在实际中相互切合。如果观念在语法上的联结反映了现实联结中的客观秩序，则这些观念是切合的。</p></blockquote><blockquote><p>📌 结论可能性的高低取决于前提联系的紧密程度。来看以下论证： 杰克参加了四月份在芝加哥举行的会议。 皮特参加了同一个会议。 他们可能已经在那里见过面了。 注意结论中的假设性，它是很恰当的。我们不能确定杰克和皮特一定在会议上见了面（我们只知道他们都在那里），但是设想他们已经见过面了也合情合理。</p></blockquote><blockquote><p>📌 17 归纳论证 到目前为止，我们所讨论的所有论证都是演绎论证。传统区分演绎论证和归纳论证的方法是：演绎论证是从一般到个别，而归纳论证则恰恰相反。这是区分两者的有效方法，但有其局限性。更准确地区分两者的方法是：演绎论证得出的是必然性结论，而归纳论证只能得出可能性结论。 作为论证形式的两种类别，演绎论证和归纳论证都具有论证的两个基本要素：前提和结论。在演绎论证中，我们只用一个正确的命题作为起点（大前提）。</p></blockquote><blockquote><p>📌 18 评定论证 让我们来做个小结：论证展现的是推理的核心——推理的过程；在最简单的形式里，它使我们从一个观点出发并接受另一个观点。在评定论证正确性的过程中，第一步要确定的是，我们所要评定的论证是否是一个真正的论证。换句话说就是，论证的两个基本要素——前提和结论，都体现出来了吗？有时，一个表面上看起来似乎是正确的论证，实际上根本找不到有效的支持证据，即使我们通过各种途径热烈地讨论过它。只有证据充足的命题可以得出结论。</p></blockquote><blockquote><p>📌 所以在面对这些观众时，这些前提就该是你要使用的。 最后一个需要注意的问题是个由来已久的忠告：了解你的听众。关于这个问题，你最好记住，虽然逻辑学是一门科学，但它同样是一门艺术。一个论证有双重的目的：得出正确的结论，说服听众接受。为了成功做到后者，在论证时，我们必须选择适合于听众的方式。这就是逻辑学艺术性的由来。 历史使人明智；诗词使人灵秀；数学使人周密；自然哲学使人深刻；伦理使人庄重；逻辑修辞学使人善辩。</p></blockquote><blockquote><p>📌 培根 英国哲学家</p></blockquote><blockquote><p>📌 虽然一些古代的哲学家认为情感与理智分别寄居于体内不同的领地，彼此征战交锋，但实际上这两者居于同一片领地，至少在理想状态下，它们应该可以融洽相处。思想，即便是最纯净的思想，也不可能完全脱离情感的浸染。因为每个思想都是人这种天生的情感动物构思出来的。 这是不可回避的事实，所以不要试图将情感完全排除在外。促使人们作出合理论证的是智力因素，是思想和它们彼此的关联，情感暗示并不能左右它。</p></blockquote><blockquote><p>📌 一个结论并不因为我们觉得美好就可以被接受，我们接受它是因为我们认为它是正确的，是必须接受的。大家一定要记住以下这个简单的基本原则：永远不要直接调动人们的情感，要努力使人们自己发现真相。只有真相，才值得人们为之欢呼雀跃。</p></blockquote><blockquote><p>📌 要始终牢记这一点：合乎逻辑是要合乎真相。除了探寻真相，任何其他目的的推理都是对逻辑的滥用。这个结论中体现的理想非常高尚，虽然人类的奋斗史并不总是如此高尚。但是理想终究是理想，永远值得追求。 有时论证会在情感的引导下变成宣泄愤怒的途径，或者是自我辩白的借口，甚至仅仅是自我膨胀的工具。由此，偶发事件取代了真相。理想的辩论，输赢并不是真正的目的，从正反双方的努力中，发现所辩论事物中蕴涵的真相才是最终目的。为了胜利不惜一切代价？“</p></blockquote><blockquote><p>📌 还有另外一种对论证起反作用的虚假假设，只是其作用方式不是那么直接。在论证中，如果你假设你的听众在某方面具备相应的知识，但实际上他们没有，那么他们接受你的结论的能力将明显地降低。经验之谈：尽可能地少用假设。</p></blockquote><blockquote><p>📌 不是说你的决定完全不合理。毕竟，以你对X学院的了解，彼得或许确实不是一名合格的人选。但是，这不是必然的。一颗闪亮的新星是可能出自于类似X学院之类的学校的。你所犯谬误的根源如下：知道一个来源一般是坏的，于是认定出于这个来源的所有都一定是坏的。这并不必然成立。 考虑我们所考察的人或事的出身肯定是必要的。但是我们必须走得更远。首先我们要问：彼得从哪里来？紧接着，更关键的问题是：他的品质如何？</p></blockquote><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>📌 注意力要求我们对所处的每个环境以及组成环境的每个要素都作出敏捷主动的反应。全神贯注与被动接受是不兼容的。不要对周边的事务漠然处之，要用心去看，用心去听。学会关注细节，不因事小而疏忽。古语有云：不积跬步，无以至千里。</p></blockquote><blockquote><p>📌 在逻辑学中，陈述有其特定的含义，它是语言上的特定表达方式，只针对可以作出真假判断的命题。</p></blockquote><blockquote><p>📌 在任何特定的情况下，对真相的确认都要去检查别人所认定或推测所得的真相在现实中是否存在依据。确认真相就是要达到主观与客观的统一。但是这里我们所要关注的焦点是事物的客观情况。如果我不能确认一个命题的真假，比如说“狗在车库里”，那么仅仅在大脑中反思狗啊、车库啊或者其他相关概念是无助于我解决这个问题的，我得亲自到车库去看看。从这一点也可以清楚地看出，为什么我们说本体真相更为基础。决定命题真假的依据是现实情况，而逻辑真相是建立在本体真相的基础之上的。</p></blockquote><blockquote><p>📌 逻辑定义的独特价值在于它揭示了所定义事物的本质。然而，当我们对一个事物没有足够深入的了解，不能抓住其本质时，这样的定义我们往往难以给出。在这种情况下，我们只能通过描述来宽泛地说明事物。好的描述是将一个事物可以观察到的现象尽可能完整详细地描述出来，其作用在于它可能会揭示出一些关于事物本质的线索。</p></blockquote><blockquote><p>📌 前提是一个支持性命题，它是一个论证的起点，包含着推理的出发点所依靠的基础事实。结论是被证明的命题，它在前提的基础上得出，并为大家所接受。复杂论证通常包含大量的前提，而且各前提之间往往相互作用，具有一定的关系。你可以有一整套相互关联的前提，其中一个可能建立在另一个前提之上，所以要摆正它们之间的关系，以便得出正确的结论。</p></blockquote><blockquote><p>📌 虽然一些古代的哲学家认为情感与理智分别寄居于体内不同的领地，彼此征战交锋，但实际上这两者居于同一片领地，至少在理想状态下，它们应该可以融洽相处。思想，即便是最纯净的思想，也不可能完全脱离情感的浸染。因为每个思想都是人这种天生的情感动物构思出来的。</p></blockquote><blockquote><p>📌 一个结论并不因为我们觉得美好就可以被接受，我们接受它是因为我们认为它是正确的，是必须接受的。大家一定要记住以下这个简单的基本原则：永远不要直接调动人们的情感，要努力使人们自己发现真相。只有真相，才值得人们为之欢呼雀跃。</p></blockquote><blockquote><p>📌 要始终牢记这一点：合乎逻辑是要合乎真相。除了探寻真相，任何其他目的的推理都是对逻辑的滥用。这个结论中体现的理想非常高尚，虽然人类的奋斗史并不总是如此高尚。但是理想终究是理想，永远值得追求。</p></blockquote><blockquote><p>📌 还有另外一种对论证起反作用的虚假假设，只是其作用方式不是那么直接。在论证中，如果你假设你的听众在某方面具备相应的知识，但实际上他们没有，那么他们接受你的结论的能力将明显地降低。经验之谈：尽可能地少用假设。</p></blockquote><blockquote><p>📌 不是说你的决定完全不合理。毕竟，以你对X学院的了解，彼得或许确实不是一名合格的人选。但是，这不是必然的。一颗闪亮的新星是可能出自于类似X学院之类的学校的。你所犯谬误的根源如下：知道一个来源一般是坏的，于是认定出于这个来源的所有都一定是坏的。这并不必然成立。</p></blockquote>',30)])])}const n=e(p,[["render",u]]);export{d as __pageData,n as default};
